import test from 'node:test';
import assert from 'node:assert/strict';
import { createCreditNote } from '../src/credits.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('createCreditNote creates a credit note for an issued invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // Total: 20570

  const r = createCreditNote(issued, { amount: 5000, reason: 'Overpaid', date: '2026-10-10' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0001');
  assert.equal(r.value.invoiceNumber, 'INV-2026-0001');
  assert.equal(r.value.customerId, 'C-002');
  assert.equal(r.value.amount, 5000);
  assert.equal(r.value.reason, 'Overpaid');
  assert.equal(r.value.date, '2026-10-10');
});

test('createCreditNote works with partially paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const partial = recordPayment(issued, { amount: 5000, date: '2026-10-08' }).value;

  const r = createCreditNote(partial, { amount: 2000, reason: 'Adjustment', date: '2026-10-10' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.status, undefined);
  assert.equal(r.value.amount, 2000);
});

test('createCreditNote works with paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const paid = recordPayment(issued, { amount: 10285, date: '2026-10-08' }).value;

  const r = createCreditNote(paid, { amount: 1000, reason: 'Refund', date: '2026-10-10' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.amount, 1000);
});

test('createCreditNote reports NOT_ISSUED for draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const r = createCreditNote(inv, { amount: 5000, reason: 'Error', date: '2026-10-10' }, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_ISSUED' });
});

test('createCreditNote reports NOT_ISSUED for null invoice', () => {
  const r = createCreditNote(null, { amount: 5000, reason: 'Error', date: '2026-10-10' }, []);
  assert.deepEqual(r, { ok: false, error: 'NOT_ISSUED' });
});

test('createCreditNote reports AMOUNT_INVALID for zero amount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const r = createCreditNote(issued, { amount: 0, reason: 'Error', date: '2026-10-10' }, []);
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote reports AMOUNT_INVALID for negative amount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const r = createCreditNote(issued, { amount: -1000, reason: 'Error', date: '2026-10-10' }, []);
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote reports AMOUNT_INVALID for fractional amount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const r = createCreditNote(issued, { amount: 5000.5, reason: 'Error', date: '2026-10-10' }, []);
  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote reports CREDIT_TOO_HIGH for amount exceeding invoice total', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // Total: 10285
  const r = createCreditNote(issued, { amount: 10286, reason: 'Error', date: '2026-10-10' }, []);
  assert.deepEqual(r, { ok: false, error: 'CREDIT_TOO_HIGH' });
});

test('createCreditNote allows amount equal to invoice total', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // Total: 10285
  const r = createCreditNote(issued, { amount: 10285, reason: 'Full refund', date: '2026-10-10' }, []);
  assert.equal(r.ok, true);
  assert.equal(r.value.amount, 10285);
});

test('createCreditNote increments credit note counter independently', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const cn1 = createCreditNote(issued1, { amount: 1000, reason: 'Refund 1', date: '2026-10-10' }, []);
  const cn2 = createCreditNote(issued2, { amount: 2000, reason: 'Refund 2', date: '2026-10-11' }, [cn1.value.number]);

  assert.equal(cn1.value.number, 'CN-2026-0001');
  assert.equal(cn2.value.number, 'CN-2026-0002');
});

test('createCreditNote separates invoice and credit note counters', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const existing = ['INV-2026-0001', 'INV-2026-0002', 'INV-2026-0003', 'CN-2026-0001'];
  const r = createCreditNote(issued, { amount: 1000, reason: 'Refund', date: '2026-10-10' }, existing);

  assert.equal(r.ok, true);
  // Should create CN-2026-0002, not INV-2026-0004
  assert.equal(r.value.number, 'CN-2026-0002');
});

test('createCreditNote handles mixed existing numbers', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const existing = [
    'INV-2026-0001',
    'CN-2026-0001',
    'INV-2026-0002',
    'CN-2026-0002',
    'INV-2026-0003',
  ];
  const r = createCreditNote(issued, { amount: 1000, reason: 'Refund', date: '2026-10-10' }, existing);

  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'CN-2026-0003');
});

test('createCreditNote resets counter for different years', () => {
  const inv2025 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-12-25',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2026 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued2025 = issueInvoice(inv2025, []).value;
  const issued2026 = issueInvoice(inv2026, ['INV-2025-0001']).value;

  const existing = ['CN-2025-0005'];
  const r2025 = createCreditNote(issued2025, { amount: 1000, reason: 'Refund', date: '2025-12-30' }, existing);
  const r2026 = createCreditNote(issued2026, { amount: 1000, reason: 'Refund', date: '2026-01-10' }, existing);

  assert.equal(r2025.value.number, 'CN-2025-0006');
  assert.equal(r2026.value.number, 'CN-2026-0001');
});

test('createCreditNote with small amount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const r = createCreditNote(issued, { amount: 1, reason: 'Penny refund', date: '2026-10-10' }, []);

  assert.equal(r.ok, true);
  assert.equal(r.value.amount, 1);
});

test('createCreditNote with large amount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // Total: 145200
  const r = createCreditNote(issued, { amount: 145200, reason: 'Full refund', date: '2026-10-10' }, []);

  assert.equal(r.ok, true);
  assert.equal(r.value.amount, 145200);
});

test('createCreditNote preserves reason field exactly', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const reasons = [
    'Customer request',
    'Pricing error - discussed with client',
    'Item damaged in shipping',
    'Quality issue',
    '',
  ];

  for (const reason of reasons) {
    const r = createCreditNote(issued, { amount: 1000, reason, date: '2026-10-10' }, []);
    assert.equal(r.ok, true);
    assert.equal(r.value.reason, reason);
  }
});

test('createCreditNote with invoice with discount', () => {
  const inv = createInvoice({
    customerId: 'C-001', // gold tier, 5% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // Total with gold discount: 19542
  const r = createCreditNote(issued, { amount: 5000, reason: 'Adjustment', date: '2026-10-10' }, []);

  assert.equal(r.ok, true);
  assert.equal(r.value.amount, 5000);
});

test('createCreditNote with invoice with voucher', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // Manually add voucher (would be done through applyVoucher on draft)
  const withVoucher = {
    ...issued,
    voucher: { code: 'WELCOME', amount: 2000 },
  };
  // Total with voucher: 20570 - 2000 = 18570

  const r = createCreditNote(withVoucher, { amount: 5000, reason: 'Refund', date: '2026-10-10' }, []);

  assert.equal(r.ok, true);
  assert.equal(r.value.amount, 5000);
});

test('createCreditNote with VAT-exempt invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // Total: 60000 (VAT-exempt)
  const r = createCreditNote(issued, { amount: 15000, reason: 'Partial refund', date: '2026-10-10' }, []);

  assert.equal(r.ok, true);
  assert.equal(r.value.amount, 15000);
});

test('createCreditNote returns proper structure', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const r = createCreditNote(issued, { amount: 5000, reason: 'Refund', date: '2026-10-10' }, []);

  assert.equal(r.ok, true);
  assert.ok(r.value.number);
  assert.ok(r.value.invoiceNumber);
  assert.ok(r.value.customerId);
  assert.equal(typeof r.value.amount, 'number');
  assert.equal(typeof r.value.reason, 'string');
  assert.ok(r.value.date);
  assert.equal(Object.keys(r.value).length, 6);
});

test('createCreditNote with multiple credits for same invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // Total: 51425

  const cn1 = createCreditNote(issued, { amount: 10000, reason: 'Partial refund 1', date: '2026-10-10' }, []);
  const cn2 = createCreditNote(issued, { amount: 20000, reason: 'Partial refund 2', date: '2026-10-12' }, [cn1.value.number]);

  assert.equal(cn1.ok, true);
  assert.equal(cn2.ok, true);
  assert.equal(cn1.value.number, 'CN-2026-0001');
  assert.equal(cn2.value.number, 'CN-2026-0002');
  assert.equal(cn1.value.invoiceNumber, 'INV-2026-0001');
  assert.equal(cn2.value.invoiceNumber, 'INV-2026-0001');
});

test('createCreditNote validates amount before credit amount check', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const r = createCreditNote(issued, { amount: -1000, reason: 'Error', date: '2026-10-10' }, []);

  assert.deepEqual(r, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote handles edge case of exact amount match', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // Total: 145200
  const r = createCreditNote(issued, { amount: 145200, reason: 'Full refund', date: '2026-10-10' }, []);

  assert.equal(r.ok, true);
  assert.equal(r.value.amount, 145200);
});

test('createCreditNote formats credit note number correctly', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const numbers = [];
  for (let i = 0; i < 5; i++) {
    const r = createCreditNote(issued, { amount: 1000, reason: 'Refund', date: '2026-10-10' }, numbers);
    numbers.push(r.value.number);
  }

  assert.equal(numbers[0], 'CN-2026-0001');
  assert.equal(numbers[1], 'CN-2026-0002');
  assert.equal(numbers[2], 'CN-2026-0003');
  assert.equal(numbers[3], 'CN-2026-0004');
  assert.equal(numbers[4], 'CN-2026-0005');
});

test('createCreditNote with malformed invoice gracefully fails', () => {
  const badInvoice = {
    status: 'issued',
    number: 'INV-2026-0001',
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ qty: 5 }], // Missing unitPrice
  };

  const r = createCreditNote(badInvoice, { amount: 1000, reason: 'Refund', date: '2026-10-10' }, []);
  assert.equal(r.ok, false);
  assert.equal(r.error, 'LINE_INVALID');
});

